export const CATEGORIES = Array.from( new Set(CAPABILITIES.map((c) => c.category)), );
export function getCapability(id: string) { return CAPABILITIES.find((c) => c.id === id); }
/** Shared tools available to every guild. */ export function commonCapabilities(): Capability[] { return CAPABILITIES.filter((c) => c.guild === "cross-guild"); }
/** A guild's own dedicated tools (excludes shared cross-guild tools). */ export function ownCapabilitiesForGuild(guild: Guild): Capability[] { return CAPABILITIES.filter((c) => c.guild === guild); }
export function guildHasOwnCapabilities(guild: Guild): boolean { return CAPABILITIES.some((c) => c.guild === guild); }

export type FieldType = "url" | "text" | "textarea" | "select" | "toggle";
export type Field = { key: string; label: string; type: FieldType; placeholder?: string; help?: string; required?: boolean; options?: string[]; default?: string | boolean; };
export type Status = "live" | "soon";
export type Guild = "mobile" | "web" | "java" | "full-stack" | "product" | "testing" | "cross-guild"; export type Provider = "ado" | "github" | "jira" | "datadog" | "internal"; export type Execution = "pipeline" | "hub-inline" | "local"; export type Source = "native" | "hub-a";
// Fixed taxonomy (NOT derived) so empty guilds still render as views. export const GUILDS: Guild[] = ["mobile", "web", "java", "full-stack", "product", "testing", "cross-guild"];
export type Capability = { id: string; name: string; /** SDLC phase this capability lives in — Plan, Design, Development, Testing, Release, Monitoring */ codename: string; /** what the SDLC phase is, shown in the detail view */ codenameWho: string; /** why this capability belongs to that phase, shown in the detail view */ codenameWhy: string; tagline: string; description: string; category: string; status: Status; /** target release quarter for 'soon' capabilities (e.g. "Q3 2026") */ targetRelease?: string; icon: string; // lucide icon key, mapped in components/icons.ts /** env var the capability reads as the per-run identity token (copilot runs only) */ tokenEnv?: string; /** estimated GitHub Copilot AI credits burned per run */ estCredits: number; /** typical wall-clock for a run, shown in UI */ estDuration: string; /** ADO pipeline this maps to (cicd/pipelines/*.yml) — pipeline execution only */ pipeline?: string; script?: string; fields: Field[];
guild: Guild; provider: Provider[]; execution: Execution; source: Source; credGate: "copilot" | "none"; };
// AI-Powered SDLC Transformation phases, grouped Planning & Analysis / Build & Quality / Delivery & Operations. const PHASE = { plan: "Plan — the Planning & Analysis phase: backlog analysis and prioritization, requirements validation and enrichment, and early gap, risk and dependency detection — so work starts with less rework and a ready, aligned backlog.", design: "Design — the Planning & Analysis phase where validated requirements are shaped and enriched into a solution before build.", development: "Development — the Build & Quality phase: AI-assisted development, code optimization and documentation/knowledge generation — cutting cycle time and manual review effort while lifting code quality.", testing: "Testing — the Build & Quality phase: test design and lifecycle quality enforcement — lifting coverage while cutting manual test effort.", release: "Release — the Delivery & Operations phase: release risk assessment and dependency/version management — so ships go out with confidence.", monitoring: "Monitoring — the Delivery & Operations phase: monitoring, anomaly detection and incident recovery — cutting production incidents and MTTR while raising reliability.", } as const;
