export const CATEGORIES = Array.from( new Set(CAPABILITIES.map((c) => c.category)), );
export function getCapability(id: string) { return CAPABILITIES.find((c) => c.id === id); }
/** Shared tools available to every guild. */ export function commonCapabilities(): Capability[] { return CAPABILITIES.filter((c) => c.guild === "cross-guild"); }
/** A guild's own dedicated tools (excludes shared cross-guild tools). */ export function ownCapabilitiesForGuild(guild: Guild): Capability[] { return CAPABILITIES.filter((c) => c.guild === guild); }
export function guildHasOwnCapabilities(guild: Guild): boolean { return CAPABILITIES.some((c) => c.guild === guild); }

export type PgVarType = "text" | "textarea" | "select";

export type PgVariable = {
  key: string;
  label: string;
  type: PgVarType;
  placeholder?: string;
  options?: string[];
};

export type PgTemplate = {
  id: string;
  name: string;
  /** filter chip + grouping — who the template is for */
  category: string;
  /** lucide icon key, mapped in components/icons.ts */
  icon: string;
  description: string;
  /** the role the model holds for the whole conversation, e.g. "a senior QA engineer" */
  persona: string;
  variables: PgVariable[];
  /** first-message body; {{key}} placeholders are filled from variable values */
  prompt: string;
};

/**
 * Template library for the AI Playground. Each template is a persona (a role the
 * model holds for the whole chat) plus a pre-written opening prompt with fill-in
 * variables, so non-technical folks (PM / QA / delivery / business) can run
 * Copilot without prompt-engineering. Output only — nothing is written back to
 * Azure DevOps. Follow-up turns keep the persona and prior context.
 */
